import{_ as a,c as e,o as p,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"易图通变卷六","description":"易图通变 - 易图通变卷六","frontmatter":{"title":"易图通变卷六","description":"易图通变 - 易图通变卷六"},"headers":[],"relativePath":"zh/classics/yitu-tongbian/007.md","filePath":"zh/classics/yitu-tongbian/007.md"}'),i={name:"zh/classics/yitu-tongbian/007.md"};function n(r,t,o,c,_,l){return p(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="易图通变卷六" tabindex="-1">易图通变卷六 <a class="header-anchor" href="#易图通变卷六" aria-label="Permalink to “易图通变卷六”">​</a></h1><p>钦定四库全书</p><p>宋雷思齐撰卜筮</p><p>洪范之稽疑曰：「择建立卜筮人，乃命卜筮。」诗曰：「尔卜尔筮，体无咎言。」曰：「卜筮偕止，会言近止。」记之月令则曰：「孟冬之月，命大史衅龟策，占兆吉凶。」宜若龟筮相须为用也。易大传曰：「探赜索隐，钩深致远，成天下之亹亹者，莫大乎蓍龟。」又曰：「以卜筮者尚其占。」则夫易宜兼卜筮之用者也。大诰曰：「宁王遗我大宝龟，绍天明即命。」金縢曰：「乃卜三龟，一习吉。」于是莫见夫筮。记又曰：「天子无筮，诸侯有守筮，天子道以筮。」于是又莫见夫卜。而</p><p>说卦则曰：「昔者圣人之作易，幽赞于神明而生蓍，参天两地而倚数，观变于阴阳而立卦，发挥于刚柔而生爻，以至和顺于道德而理于义，穷理尽性以至于命。」乃独归夫筮而未始及夫卜也。由筮命蓍，而蓍筮之用著于大衍之数，实详且备，而龟之卜则莫之一语及也。虽一间见谓龟为卜、蓍为筮之说于别出，而愚自童矿，习见世之常占掷钱以画卦爻，云自京房始矣。且贾公彦亦以画卦之单拆重交之爻谓以钱，复见有假于龟之刳中以布其钱者，又杂于传记，谓卜得某卦之某卦之大凡。且人有常言，实称卜卦，故亦随之等视筮龟、卜筮为一槩，未尝以为意也。盖尝见周礼春官之属，大卜掌三兆之法，一曰玉兆，二曰瓦兆，三曰原兆。其经兆之体皆百有二十，其颂皆千有二百。其下有卜师掌开龟兆，龟人掌六龟，以其方色与体辨之。大卜又掌三易之法，一曰连山，二曰归藏，三曰周易，其经卦皆八，其别皆六十有四。其下有筮人掌三易之九筮，以辨吉凶。凡国之大事，先筮而后卜，上春相筮，凡国事共筮。然后知卜之用龟则以兆，其书兆之体颂至百有二十、千有二百之多。而易之筮用蓍，固未始出于六十四卦之外。则卜自卜，筮自筮，未始相为用也。况洪范固有龟从筮从，龟从筮逆，龟筮共违于人之别，则其卜筮之分校然，其辨白黑，未始若后世说卜筮者，樊然殽乱，至若是之甚，心甚异之。由是于左传之类，究其成验，乃判然识卜筮之道，卜者未尝引易之筮，筮者未尝引龟之卜也。今疏列为征。</p><p>有专卜而不筮者：晋惠公之在梁，梁伯妻之。梁嬴孕过期，卜招父与其子卜之。子曰：「将生一男一女。」招曰：「然。男为人臣，女为人妾。」名男曰圉，女曰妾。及圉西质于秦，妾为宦女焉。邾文公卜迁于绎，史曰：「利于民而不利于君。」邾子曰：「苟利于民，迁也。天生民而树之君，以利之也。民既利矣，孤必与焉。」既迁，而邾子卒。齐侯戒师期，将以伐鲁，而有疾。医曰：「不及秋，将死。」鲁文公闻之，卜曰：「尚无及期。」叔仲惠伯令龟，卜楚丘占之，曰：「齐侯不及期，非疾也。君亦不闻，令龟有咎。」既而齐懿公弑，文公先薨，惠伯亦卒。楚王与叶公枚卜子良以为令尹。沈尹朱曰：「吉。过于其志。」叶公曰：「王子而相国，过将何为？」他日，改卜子国以为令尹。若是者，见卜之未尝及于筮卦也。有筮而不卜者。毕万筮仕于晋，遇屯之比。□廖占之，曰：「吉。屯固比入，吉孰大焉，其必蕃昌。震为主，车从马，足居之，兄长之，母覆之，众归之，六体不易，合而能固，安而能杀，公侯之卦也。公侯之子孙，必复其始。」秦伯伐晋，卜徒父筮之，曰：「吉。涉河，侯军败。」诘之，对曰：「乃大吉也。三败，必获晋君。其卦遇蛊，䷑其繇曰：千乘三去，三去之余，获其雄狐。夫狐蛊，必其君也。蛊之贞，风也；其悔，山也。岁云秋矣，我落其实，而取其材。实落材亡，不败何待？」三败及韩。晋侯逆秦师，战于韩原。秦获晋侯以归。晋侯伐郑，楚子救郑，相遇于鄢陵。公筮之，史曰：「吉。」卦遇复，䷗曰：「南国蹙，射其元王，中厥目。国蹙王伤，不败何待？」及战，吕锜射共王，中目。王曰：「天败楚也，吾不可待。」乃宵遁。晋献公筮嫁伯姬于秦，遇归妹之睽，□史苏占之，曰：「不吉。其繇曰：士刲羊，亦无血也。女承筐，亦无贶也。西邻责言，不可偿也。归妹之睽，犹无相也。震之离，亦离之震，为雷为火，为嬴败姬。车说其輹，火焚其旗，不利行师，败于宗丘。归妹之睽，寇张之弧，侄其从姑，六年其逋。逃归其国，而弃其家，明年其死于高梁之虚。」若是四者，筮则有卦，而无复卜兆辞也。且前之屯、复、蛊三卦，其繇固皆非易之辞。后之归妹之睽，卦辞近周易，而亦非也，槩可想见。连山、归藏之易，其筮法同，而繇辞异也。</p><p>有兼用卜筮，而卜有辞，筮有有辞者。鲁成季之将生也，桓公使卜楚丘之父卜之，曰：「男也，其名曰友，在公之右，间于两社，为公室辅。季氏亡，则鲁不昌。」又筮之，遇大有之乾，□曰：「同复于父，敬如君所。」及生，有文在其手曰「友」，遂以命之。若是者，卜与筮各有筮辞之卦辞，亦非周易辞也。</p><p>有先卜后筮者。晋献公欲以骊姬为夫人，卜之不吉，筮之吉。公曰：「从筮。」卜人曰：「筮短龟长，不如从长。且其繇曰：专之渝，攘公之羭。一薰一犹，十年尚犹有臭。必不可。」弗听，立之，生奚齐，乃谮太子申生，至于缢死。遂立奚齐，卒乱晋。有先筮而后卜者。卫侯梦于北宫，见人登昆吾之观，被发而噪曰：「登此昆吾之虚，緜緜生之瓜。余为浑良夫，叫天无辜。」公亲筮之，胥弥赦占之，曰：「不害。」卫侯贞卜，繇曰：「如鱼竀尾，衡流而方羊。裔焉大国，灭之将亡。阖门塞窦，乃自后逾。」冬十月，晋复伐卫，入其郛。卫出庄公而与晋平。晋立襄公之孙般师而还。若是二者，虽先卜后筮，先筮后卜则殊。筮无卦辞，卜乃有繇，然为卜为筮，不比而同也。其若晋献公卜伐骊戎，史苏占之曰：「胜而不吉。」公曰：「何谓也？」对曰：「遇兆曰：挟以衔骨，齿牙为猾，戎夏交捽，是交胜也。臣故云。且惧有口，携民国私心焉。」公曰：「何口之有？口在寡人，寡人弗受，谁其兴之？」对曰：「苟可以携，其入也必甘受，逞而不知，胡可壅也。」公弗听，遂伐骊戎，克之，获骊姬以归，卒以乱国。若是者，卜独有繇辞而不及筮，则国语犹然也，辞与左传尚未相远也。若家语谓孔子尝自筮，得贲卦，䷕愀然有不平之色。子张进曰：「卜者得贲卦，吉也，而夫子之不平，何也？」子曰：「以其离邪。在周易，山下有火，贲，非正色之卦也。夫质也者，黑白宜正焉。今得贲，非吾兆也。吾闻丹漆不文，白玉不雕，何也？质有余，不受饰也。」由今观之，是可疑者。且既谓孔子自筮，何子张乃谓之卜？况其辞与易不类。贲之彖曰：「贲，柔来而文刚，分刚上而文柔。故小利有攸往，天文也；文明以止，人文也。观乎天文，以察时变，观乎人文，以化成天下。」何夫子于彖取其文，于筮独尚其质，自相抵牾，遽至于此？愚故不敢以家语为信，盖左氏于专筮而不卜，列于专者尚多有之，不克枚举，悉以周易之辞推之。周易独行至今，人莫不审悉。自家语一事之外，卜之用龟兆，筮之用蓍卦，断断乎未尝自为纷𫄙也。抑亦见连山、归藏之与周易而为三，其经卦皆八，其别皆六十有四者，于体为不诬。连山、归藏今莫之见，例此溯求，犹仿佛一二，曷尝如后之俗，群然同讹，习称蓍筮为卜卦哉！说者谓易经由混于卜筮占兆得免秦火，固亦或者。然其谓太卜所掌经兆之体皆百二十，其颂皆千二百，乃无得见者，岂所谓占兆可脱于火者亦不免邪？昔汉文自代来卜，得大横，繇曰：「大横庚庚，余为天王，夏启以光。」释者谓大横，龟之正横，是其体也。文帝有王之象，则卜兆汉初似尚存，而后世不传。唯北齐高洋欲篡东魏，卜于李密，亦谓大横曰：「汉文之兆也。」愚意后特谄洋以成篡耳，焉可尽信哉？后世卜兆之书，没没不闻多中，何哉？嗟乎！合其体既三百六十，分其颂乃三千六百之富，宜乎其不存也。诚使其存，谁其及之哉？何以明之？连山、归藏，世固罔然惟周易一书，卦之少唯六十有四，爻之多止于三百六十有四，更三古四圣之所作述，今未云至精至变，至于至神之用。至若经卦与其别者，以辞而已，杂然注释者皆是也。及问其蓍筮之惟变所适者，则茫乎实莫知其为何事。若是者，尚欲与之语易，不亦难矣哉！愚因论卜筮之不可槩同，尝浩叹及之之卦，</p><p>圣人有以见天下之赜，而拟诸形容，象其物宜，是故谓之象。</p><p>圣人有以见天下之动，而观其会通，以行其典礼，繋辞焉，以断其吉凶，是故谓之爻。极天下之赜者存乎卦，鼓天下之动者存乎辞，化而裁之存乎变，推而行之存乎通。然则变而通所以尽利，通其变所以成文。八卦成列，而象在中，因而重之，而爻在中，刚柔相推，而变在中，繋辞命之，而动在中矣。八卦以象告，爻彖以情言，变通以利言，吉凶以情迁。又曰：「爻象动乎内，吉凶见乎外，功业见乎变，圣人之情见乎辞。」既曰鼓天下之动者存乎辞，系辞而命之，动在其中，则又曰「繋辞焉以断其吉凶」，曰「辨吉凶者存乎辞」，则辞也者，易道之所必不得已也。是故易之为书，其道屡迁，变动不居，周流六虚，上下无常，刚柔相易，不可为典要，唯变所适。卦有大小，辞有险易。辞也者，各指其所之。然则「指其所之」之「之」一字，特指其变动之所之适也。易，变易也，所以见天下之动而鼓天下之动者，莫不于是乎观。故易之筮谓其爻变而动而有所之适者，为某卦之某卦。今之谓辞指所之者，为之卦发也。韩康伯于此「指所之」之下无注，孔颖达疏曰：「各指所之，谓爻卦之辞各斥其爻卦之之适也。」若之适于善，则其辞善；之适于恶，则其辞恶而已。夫以「之」之一字以训「适」，非不然也。谓卦之变、爻之动，则未足以明其辞之所之也。请亦以左传明之。陈敬仲之少也，周史有以周易见陈侯，陈侯使筮之，遇观之「否」，□乃「观」之四爻之否之四爻也，故史指「观」之四爻之辞曰：「观国之光，利用宾于王。」因以知其代陈有国也。晋文公之纳王也，筮之，遇大有之「睽」，□乃「大有」之三之「睽」之三也，故卜偃指「大有」之三爻曰：「吉，公用享于天子之卦也。」战克而王享，吉孰大焉？ 大有九三，易以「享」为「亨」，然「亨」本通音为「享」。 齐崔杼欲取棠公之嫠，东郭姜筮之，遇困之大过，□乃「困」之三之大过之三也。史皆曰：「吉。」以示陈文子，故文子指「困」之三爻曰：「夫从风，风损妻，不可取也。」且其繇曰：「困于石，据于蒺藜，入于其宫，不见其妻，凶。」且释之曰：「困于石，往不济也；据于蒺藜，所恃伤也；入于其宫，不见其妻，凶，无所归也。」崔杼必取棠姜，终以乱而家遂灭。叔孙穆子之生，庄叔以周易筮之，遇明夷之「谦」，□乃「明夷」之初之谦之初也。以示卜楚丘，曰：「明而未融，其当旦乎？」之谦当鸟，故曰：「明夷于飞。」明而未融，故曰：「垂其翼。」象日之动，故曰：「君子攸行。」当三在旦，故曰：三日不食。离为火，火焚山败。于人为言，言败为谗，故曰：「有攸往，主人有言。」言必谗也。盖明夷初爻辞也。其卒以竖牛之乱，筮占无一不验者。卫襄夫人无子，嬖人婤姶生孟絷。孔成子梦康叔谓已：「立元，余使羁之孙圉与史苟相之。」史朝亦梦康叔谓已：「余命而子苟与孔烝𬬺之曾孙圉相元。」史朝见成子而告之梦协。韩宣子为正聘于诸侯之岁，婤姶生子，名之曰元。孟絷之足不良，能行。成子以周易筮之，曰：「元尚享卫国，主其社稷。」遇屯之比，□又曰：「余尚立絷，尚克嘉之。」遇屯䷂以示史朝，朝曰：「元亨，又何极焉？」成子曰：「非长之谓也。」曰：「康叔命之，可谓长矣。是以繇曰：利建侯。嗣吉何建？建非嗣也。二卦皆云，子其建之。」康叔命之，二卦告之，筮袭于梦，武王所用也。盖再遇屯，卦辞皆曰「元亨」，而屯变于初，故之比之屯之初爻辞曰：「盘桓，利居贞，利建侯。」于是立元。南蒯之将叛也，枚筮之，遇坤之比，□曰：「黄裳元吉。」以为大吉，示子服惠伯，曰：「即欲有事，何如？」惠伯曰：「吾尝学此矣，忠信之事则可，不然必败。」黄，中之色也；裳，下之饰也；元，善之长也。中不中，不得其色；下不共，不得其饰。事不善，不得其极。非此三者不当。且夫易不可以占险，盖由坤之五之比之五也，故释以坤五之辞也。南蒯卒以叛，至于亡。故尝例乎是数者而夷考之传，盖尚多有之，皆以所之之卦、所动之爻言之。夫之卦也者，占变之事也。易有圣人之道，则谓以动者尚其变，以筮者尚其占，故通变之谓事，极数知来之谓占，占事则有之卦也。抑古之学易者，不惟占也，君子所居而安者，易之序也；所乐而玩者，爻之辞也。居则观其象而玩其辞，动则观其变而玩其占。不惟占则有之卦也，凡说诸心，研诸虑，事会所适，言意所致，引伸触类，亦未始不用之卦也。楚子围郑，克之，晋师救郑，荀桓子闻郑及楚平，欲还，曰：「无及于郑而勦民，焉用？」随武子曰：「善。」彘季不可。以中军佐济。知庄子曰：此师殆哉！周易有之，在师之临□曰：「师出以律，否臧凶。指师之初之临之初也。」郑游吉至自楚，告子展曰：「楚子将死矣，不修政德，而贪昧于诸侯，以逞其愿，欲久得乎？」在复之颐□曰：「迷复，凶。其楚子之谓乎？」指复之上之颐之上也。郑公子曼满与王子伯廖语，欲为卿，伯廖告人曰：「无德而贪，其在周易丰之离□弗过之矣。」盖指丰之上之离之上也。其辞曰：「丰其屋，蔀其家，𬮭其户，阒其无人，三岁不觌，凶也。」间一岁，郑人果杀之。若是三者，尚不过槩举其卦之一爻之所之之为然也。至于蔡墨对魏献子之问龙见绛郊，则直曰：周易有之，在乾之姤䷀曰「潜龙勿用」，其同人䷀曰见龙在田，其大有䷀曰飞龙在天，其夬䷀曰元龙有悔。其坤䷀曰见群龙无首，吉。坤之剥□曰「龙战于野。」此虽于象龙、真龙之事有不容于理讨，然其所举乾坤之爻凡六，必皆互以乾坤反复相之之爻辞以相校而明其所之者，谓全易之卦六十有四，其爻三百八十有四，变之所之，率由是道也。是足以溯明易大传之辞也者，各指其所之者，非为他设也，为之卦设也。是固所以见天下之动而观其会通，以行其典礼，断其吉凶，化而裁之，推而行之，惟变所适也。变之所适，之卦之谓也。故曰：爻象动乎内，吉凶见乎外，功业见乎变，圣人之情见乎辞。卦有大小，辞有险易，辞也者，各指其所之。学者因之以是审于观变以立卦，倚数以生爻，极深乎至精，研几乎至变，以至于至神，和顺道德而理于义，穷理尽性以至于命，胸中包有全易之体用，斯其至矣。易筮通变卷上。</p>',10)])])}const m=a(i,[["render",n]]);export{h as __pageData,m as default};
